<?php $money = static fn($value) => 'R$ ' . number_format((float) $value, 2, ',', '.'); $income = (float) ($summary->income ?? 0); $expense = (float) ($summary->expense ?? 0); ?>
<section class="hero-row compact-hero"><div><span class="eyebrow">Análise dos seus dados</span><h2 class="page-heading">Relatórios</h2><p class="page-subtitle">Filtre o período e entenda seu fluxo financeiro.</p></div><div class="hero-actions"><a class="button button-secondary" href="/relatorios/csv?<?= http_build_query($filters) ?>">Exportar CSV</a><button class="button button-ghost" type="button" onclick="window.print()">Imprimir / PDF</button></div></section>
<form method="get" class="filter-card report-filters"><label class="field"><span>De</span><input type="date" name="date_from" value="<?= htmlspecialchars($filters['date_from']) ?>"></label><label class="field"><span>Até</span><input type="date" name="date_to" value="<?= htmlspecialchars($filters['date_to']) ?>"></label><label class="field"><span>Tipo</span><select name="type"><option value="">Todos</option><option value="income" <?= ($filters['type'] ?? '') === 'income' ? 'selected' : '' ?>>Receitas</option><option value="expense" <?= ($filters['type'] ?? '') === 'expense' ? 'selected' : '' ?>>Despesas</option></select></label><label class="field"><span>Conta</span><select name="account_id"><option value="">Todas</option><?php foreach ($accounts as $account): ?><option value="<?= (int) $account->id ?>" <?= ((int) ($filters['account_id'] ?? 0) === (int) $account->id) ? 'selected' : '' ?>><?= htmlspecialchars($account->name) ?></option><?php endforeach; ?></select></label><button class="button button-primary" type="submit">Aplicar filtros</button></form>
<section class="metrics-grid report-metrics"><article class="metric-card"><span class="metric-label">Receitas recebidas</span><strong class="metric-value positive"><?= $money($income) ?></strong></article><article class="metric-card"><span class="metric-label">Despesas pagas</span><strong class="metric-value negative"><?= $money($expense) ?></strong></article><article class="metric-card"><span class="metric-label">Resultado</span><strong class="metric-value <?= $income - $expense >= 0 ? 'positive' : 'negative' ?>"><?= $money($income - $expense) ?></strong></article><article class="metric-card"><span class="metric-label">Pendências</span><strong class="metric-value"><?= $money($summary->pending_expense ?? 0) ?></strong><span class="metric-note">Despesas a pagar</span></article></section>
<div class="dashboard-grid lower-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Despesas por categoria</span><h3>Onde o dinheiro saiu</h3></div></div><?php if (!$expenseRanking): ?><div class="empty-state compact"><p>Sem despesas no período.</p></div><?php else: ?><div class="source-list"><?php foreach ($expenseRanking as $row): ?><div class="source-item"><span class="rank-number">•</span><span><strong><?= htmlspecialchars($row->label) ?></strong><small><?= (int) $row->items ?> lançamento(s)</small></span><b class="negative"><?= $money($row->total) ?></b></div><?php endforeach; ?></div><?php endif; ?></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Receitas por categoria</span><h3>Principais fontes</h3></div></div><?php if (!$incomeRanking): ?><div class="empty-state compact"><p>Sem receitas no período.</p></div><?php else: ?><div class="source-list"><?php foreach ($incomeRanking as $index => $row): ?><div class="source-item"><span class="rank-number"><?= $index + 1 ?></span><span><strong><?= htmlspecialchars($row->label) ?></strong><small><?= (int) $row->items ?> lançamento(s)</small></span><b class="positive"><?= $money($row->total) ?></b></div><?php endforeach; ?></div><?php endif; ?></section></div>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">Dados detalhados</span><h3>Lançamentos do período</h3></div><span class="muted-text"><?= count($transactions) ?> itens exibidos</span></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Descrição</th><th>Tipo</th><th>Categoria</th><th>Conta</th><th>Valor</th><th>Status</th></tr></thead><tbody><?php foreach ($transactions as $item): ?><tr><td data-label="Data"><?= date('d/m/Y', strtotime($item->transaction_date)) ?></td><td data-label="Descrição"><?= htmlspecialchars($item->description) ?></td><td data-label="Tipo"><?= $item->type === 'income' ? 'Receita' : ($item->type === 'expense' ? 'Despesa' : 'Transferência') ?></td><td data-label="Categoria"><?= htmlspecialchars($item->category_name ?? '—') ?></td><td data-label="Conta"><?= htmlspecialchars($item->account_name) ?></td><td data-label="Valor" class="<?= $item->type === 'income' ? 'positive' : 'negative' ?>"><?= $money($item->amount) ?></td><td data-label="Status"><?= htmlspecialchars($item->status) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
